// The same fixed-length rig and vector renderer are used for the preview and canvas.
function presetState(row){
 const previous=P; P=structuredClone(initial);
 const [,category,tilt,bend,headTilt,le,lw,re,rw,lk,la,rk,ra]=row;
 rotation('waist',tilt); rotation('chest',bend); rotation('head',headTilt);
 for(const [k,a] of Object.entries({le,lw,re,rw,lk,la,rk,ra}))setAngle(k,constrainAngle(k,radians(a)));
 // Hands follow forearms; feet remain in a plausible direction relative to the shin.
 for(const k of ['lh','rh'])rotation(k,0);
 for(const k of ['lf','rf']){const a=axis(parent[k]);const desired=radians(k==='lf'?135:45);setAngle(k,constrainAngle(k,desired));}
 const coords=Object.values(P),xs=coords.map(q=>q[0]),ys=coords.map(q=>q[1]);
 translateTree('pelvis',[200-(Math.min(...xs)+Math.max(...xs))/2,230-(Math.min(...ys)+Math.max(...ys))/2]);
 // Place the nearer forearms in front of the torso for folded-arm gestures.
 let order=[...defaults];
 if(category==='Gestures'||category==='Resting'||category==='Exercise'||row[0]==='Arms crossed'||row[0]==='Hands clasped'||row[0]==='Hands on hips'){
  const front=['lw','rw','lh','rh'];order=order.filter(k=>!front.includes(k)).concat(front);
 }
 if(row.length>13) throw Error('Invalid preset row');
 if(['Seated — Everyday','Car Seat — Window Actions','Fashion — Allure & Editorial','Phone & Technology','Household & Kitchen','Street & Errands'].includes(category)){
  const side=category==='Car Seat — Window Actions'?(row[0].startsWith('Passenger')?'r':'l'):(Math.cos(radians(lk))+Math.cos(radians(rk))>0?'r':'l');
  const far=side==='r'?'l':'r';
  // Side-on seating uses complete back-to-front limb chains; forearms and hands can overlap the torso.
  order=[far+'f',far+'a',far+'k',side+'f',side+'a',side+'k',far+'e','pelvis','waist','chest','neck','head',side+'e',far+'w',far+'h',side+'w',side+'h'];
  if(/behind (the |)head|behind back|chair back|bench back|sofa with arm on back/i.test(row[0])){
   const behind=[far+'e',far+'w',far+'h'];order=behind.concat(order.filter(k=>!behind.includes(k)));
  }
 }
 if(category==='Emotions'){
  const front=['le','re','lw','rw','lh','rh'];
  order=order.filter(k=>!front.includes(k)).concat(front);
  if(/hands behind back/i.test(row[0])){order=front.concat(order.filter(k=>!front.includes(k)));}
  if(/back of the head/i.test(row[0])){const back=['le','lw','lh'];order=back.concat(order.filter(k=>!back.includes(k)));}
  if(/hugging knees/i.test(row[0])){const legs=['lf','rf','la','ra','lk','rk'];order=order.filter(k=>!legs.includes(k)&&!front.includes(k)).concat(legs,front);}
 }
 const result={P:structuredClone(P),layers:order};P=previous;return result;
}
