window.addEventListener('message',event=>{
 if(event.source!==parentWindow||event.origin!==location.origin||event.data?.type!=='popai-pose:load')return;
 const state=event.data.state;
 if(validPose(state)){
  P=structuredClone(state.P);layers=[...state.layers];visible={...state.visible};widths={...state.widths};
  if(['dark','ink'].includes(state.appearance))$('#appearance').value=state.appearance;
  if(typeof state.detail==='boolean')$('#detail').checked=state.detail;
  if(['paper','dark'].includes(state.exportStyle))$('#exportStyle').value=state.exportStyle;
  if(typeof state.transparent==='boolean')$('#transparent').checked=state.transparent;
  history=[];future=[];renderAll();
 }
 $('#poseSketch').hidden=!event.data.fromSketch;
});
const parentWindow=window.parent;
