let exportingPose=false;
async function sendPose(){
 if(exportingPose)return;
 exportingPose=true;$('#poseSketch').disabled=true;
 let url;
 try{
  const state=poseData();
  const transparency=$('#transparent');
  let exported;
  try{transparency.checked=true;exported=exportSvg();}
  finally{transparency.checked=state.transparent;}
  const {xml,w,h}=exported;
  url=URL.createObjectURL(new Blob([xml],{type:'image/svg+xml'}));
  const im=new Image();im.src=url;await im.decode();
  const scale=Math.min(3,1440/Math.max(w,h));
  const c=document.createElement('canvas');c.width=Math.max(1,Math.ceil(w*scale));c.height=Math.max(1,Math.ceil(h*scale));
  const ctx=c.getContext('2d');
  ctx.drawImage(im,0,0,c.width,c.height);
  const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));
  if(!blob)throw Error('PNG export failed');
  parentWindow.postMessage({type:'popai-pose:submit',destination:'sketch',blob,state},location.origin);
 }catch(error){status(error.message);}
 finally{if(url)URL.revokeObjectURL(url);exportingPose=false;$('#poseSketch').disabled=false;}
}
